import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\\(.+?\\)|\\w') -> dict:
    """Extract regex matches from all text files in a directory."""
    if regex_pattern == r'\\(.+?\\)|\\w':
        regex_pattern = r'\(.+?\)|\w'

    matches_by_file = {}

    for file_path in glob.glob(os.path.join(directory_path, "*.txt")):
        with open(file_path, "r", encoding="utf-8") as file:
            matches_by_file[os.path.basename(file_path)] = re.findall(
                regex_pattern, file.read()
            )

    return matches_by_file

import subprocess
import os
import shutil
import sys

# Constants
DIRECTORY = r'c:\Program Files\VMware\VMware Server'
BACKUP_DIRECTORY = r'c:\Program Files\VMware\VMware Server\Backup'

def task_func(filename):
    source_path = os.path.join(DIRECTORY, filename)

    try:
        os.makedirs(BACKUP_DIRECTORY, exist_ok=True)
        shutil.copy2(source_path, BACKUP_DIRECTORY)
    except (OSError, shutil.Error):
        return -1

    try:
        return subprocess.call([source_path])
    except OSError:
        return -1
